The error message suggests that the variable `image_links` might be `None`. This could happen if there are no matching elements found on the webpage. To handle this situation, we can add an additional check after finding the script tags to see if any images were actually found:

```python
def get_image_links(soup):
    script_tags = soup.find_all('script', {'id': 'initial-state'})
    image_links = []

    for script_tag in script_tags:
        try:
            data = json.loads(script_tag.contents[0])
            resource_data = data['resources']['data']
            images = []

            for key in resource_data:
                if key.startswith('PinResource'):
                    pin = resource_data[key]['data']
                    if pin and 'images' in pin:
                        images.append(pin['images']['orig']['url'])

            # Check if any images were found
            if images:
                image_links.extend(images)
        except Exception as e:
            print(f"Error parsing script tag: {e}")

    return image_links
```

